// Actual adapter packet parity/semantic lineage bounds; no graphics or game.
#include "garment_service.hpp"
#include <iostream>
using namespace malemod::witcher;
static void Check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
static std::vector<char> Bytes(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char** argv){try{
 if(argc!=6&&argc!=7)throw std::runtime_error("usage: garment_binding_test old002 new003 pin renderHash reportDir [existingMeasured003Input]");
 GarmentBindings previous(argv[1],argv[3],argv[4]),current(argv[2],argv[3],argv[4]);
 Check(current.root==previous.root&&current.contours==previous.contours&&current.triangles==previous.triangles&&current.bodyContour==previous.bodyContour&&current.bodyTriangles==previous.bodyTriangles,"Semantic extension changed full anatomy, measured routes or body contacts");
 Check(current.contours[2].size()==17555&&current.triangles.size()==35040&&current.bodyContour.size()==8399&&current.bodyTriangles.size()==15930,"Actual native anatomy/body sample topology differs");
 const unsigned expected[]={5448,2993,3851,3771};for(unsigned i=0;i<4;i++){Check(previous.anatomyRegions[i].empty(),"Legacy packet invented semantic regions");Check(current.anatomyRegions[i].size()==expected[i],"Measured native semantic lineage count differs");}
 auto old=Bytes(argv[1]),bytes=Bytes(argv[2]);Check(bytes.size()>old.size()&&std::equal(old.begin()+8,old.end(),bytes.begin()+8),"MMGRB003 changed previous native packet fields");
 std::filesystem::path report(argv[5]);std::filesystem::create_directories(report);auto reject=[&](std::vector<char> corrupt,const char* name){auto path=report/name;std::ofstream f(path,std::ios::binary);f.write(corrupt.data(),corrupt.size());f.close();bool caught=false;try{GarmentBindings invalid(path,argv[3],argv[4]);}catch(const std::exception&){caught=true;}Check(caught,"Malformed semantic packet accepted");};
 auto corrupt=bytes;unsigned invalid=unsigned(current.contours[2].size());std::memcpy(corrupt.data()+corrupt.size()-4,&invalid,4);reject(corrupt,"out-of-bounds.bindings");corrupt=bytes;unsigned duplicate=current.anatomyRegions[0][0];std::memcpy(corrupt.data()+corrupt.size()-4,&duplicate,4);reject(corrupt,"overlap.bindings");corrupt=bytes;corrupt.pop_back();reject(corrupt,"incomplete.bindings");
 if(argc==7){auto input=garment_capture::ReadInput(argv[6]);Check(input.anatomy.size()==current.contours[2].size()&&input.anatomyTriangles==current.triangles,"Previous captured anatomy topology differs from current measured semantics");for(unsigned i=0;i<input.anatomy.size();i++){const auto& donors=input.anatomy[i].lineage.donors;Check(donors[0].surface==malemod::garments::Surface::Anatomy&&donors[0].vertex==current.contours[2][i]&&donors[0].weight==1,"Semantic input uses a different captured native anatomy lineage");for(unsigned d=1;d<donors.size();d++)Check(donors[d].weight==0,"Semantic capture contains additional native anatomy donors");}input.anatomyRegions=current.anatomyRegions;garment_capture::WriteInput(report/"measured-with-regions.input",input);auto read=garment_capture::ReadInput(report/"measured-with-regions.input");Check(read.anatomyRegions==input.anatomyRegions&&read.anatomyTriangles==input.anatomyTriangles&&read.bodyTriangles==input.bodyTriangles,"Measured semantic capture roundtrip differs");for(unsigned i=0;i<input.anatomy.size();i++)Check(read.anatomy[i].position==input.anatomy[i].position&&read.anatomy[i].normal==input.anatomy[i].normal,"Measured semantic input rewrote actual native anatomy coordinates");}
 std::ofstream proof(report/"semantic-proof.json");proof<<"{\"contractVersion\":3,\"previousNativeFieldsExact\":true,\"fullAnatomyVertices\":17555,\"fullAnatomyTriangles\":35040,\"bodyVertices\":8399,\"bodyFaces\":15930,\"regionCounts\":[5448,2993,3851,3771],\"malformedBoundsOverlapTruncationRejected\":true,\"observedGameplay\":false}\n";
 std::cout<<"PASS actual MMGRB002/003 full native field parity, source semantic lineage counts and malformed bounds/overlap/truncation rejection\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
